package chat.vch.mobile;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import chat.vch.*;
import chat.vch.Models.*;
import java.io.*;
import java.nio.file.Path;
import java.nio.file.Files;
import java.util.*;
import java.util.concurrent.*;

public final class MainActivity extends Activity {
    private final ExecutorService work=Executors.newSingleThreadExecutor();
    private final Handler handler=new Handler(Looper.getMainLooper());
    private LinearLayout root,messages;
    private TextView status;
    private EditText input;
    private Spinner servers,channels;
    private boolean busy,unlocking,external;
    private int imagePurpose;
    private SavedServer selected;
    private Channel channel;
    private SavedServer pictureServer;
    private Channel pictureChannel;
    private final Runnable poll=new Runnable(){public void run(){if(AppSession.core!=null&&!busy){execute(()->{boolean changed=false;for(SavedServer s:AppSession.core.state.servers)if(AppSession.core.connected(s))changed|=AppSession.core.poll(s);return changed;},value->{if((Boolean)value)refreshChannels();});}handler.postDelayed(this,2000);}};
    protected void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE,WindowManager.LayoutParams.FLAG_SECURE);}
    protected void onResume(){super.onResume();external=false;if(AppSession.core==null)unlock();else showMain();handler.removeCallbacks(poll);handler.postDelayed(poll,2000);}
    protected void onStop(){super.onStop();handler.removeCallbacks(poll);if(!external){AppSession.lock();selected=null;channel=null;if(root!=null)root.removeAllViews();}}
    protected void onDestroy(){handler.removeCallbacks(poll);work.shutdownNow();super.onDestroy();}
    private void unlock(){if(unlocking)return;unlocking=true;LinearLayout form=column();EditText password=edit("Decryption password",true),confirm=edit("Confirm new password",true);form.addView(password);Path file=getFilesDir().toPath().resolve("data.vault");boolean create=!Files.exists(file);if(create)form.addView(confirm);
        new AlertDialog.Builder(this).setTitle(create?"Create VCH vault":"Unlock VCH").setView(form).setCancelable(false).setPositiveButton("Unlock",(d,w)->{char[] p=password.getText().toString().toCharArray();String q=confirm.getText().toString();password.setText("");confirm.setText("");unlocking=false;if(create&&!Arrays.equals(p,q.toCharArray())){Arrays.fill(p,'\0');error(new Exception("Passwords do not match"));unlock();return;}execute(()->new ClientCore(new Vault(file,p)),result->{AppSession.core=(ClientCore)result;showMain();});}).setNegativeButton("Exit",(d,w)->{unlocking=false;finish();}).show();
    }
    private void showMain(){root=column();root.setBackgroundColor(Color.rgb(244,244,244));TextView title=label("VCH / Conversations",24);title.setTextColor(Color.WHITE);title.setBackgroundColor(Color.rgb(22,22,22));title.setPadding(16,24,16,24);root.addView(title);
        LinearLayout actions=new LinearLayout(this);actions.addView(button("Join",this::join));actions.addView(button("Profile",this::profile));actions.addView(button("Audio",this::audio));actions.addView(button("Lock",()->{AppSession.lock();showLocked();}));root.addView(actions);
        servers=new Spinner(this);root.addView(servers);channels=new Spinner(this);root.addView(channels);LinearLayout tools=new LinearLayout(this);tools.addView(button("Connect",this::connect));tools.addView(button("Voice",this::voice));tools.addView(button("Image",()->pick(1)));root.addView(tools);
        ScrollView scroll=new ScrollView(this);messages=column();scroll.addView(messages);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout compose=new LinearLayout(this);input=edit("Message",false);compose.addView(input,new LinearLayout.LayoutParams(0,-2,1));compose.addView(button("Send",this::send));root.addView(compose);status=label("Saved history is available offline",12);root.addView(status);setContentView(root);
        servers.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,AppSession.core.state.servers));servers.setOnItemSelectedListener(new Selection(){public void chosen(int i){selected=AppSession.core.state.servers.get(i);refreshChannels();}});
        channels.setOnItemSelectedListener(new Selection(){public void chosen(int i){if(selected!=null&&i<selected.channels.size()){channel=selected.channels.get(i);render();}}});
        if(!AppSession.core.state.servers.isEmpty()){selected=AppSession.core.state.servers.get(0);refreshChannels();}
    }
    private void showLocked(){root.removeAllViews();unlock();}
    private void refreshChannels(){if(selected==null||channels==null)return;String previous=channel==null?"":channel.id;channels.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,selected.channels));int index=0;for(int i=0;i<selected.channels.size();i++)if(selected.channels.get(i).id.equals(previous))index=i;if(!selected.channels.isEmpty()){channels.setSelection(index);channel=selected.channels.get(index);}render();}
    private void render(){messages.removeAllViews();if(channel==null)return;messages.addView(label(channel.toString(),24));if(channel.type.equals("voice")){messages.addView(label("Half-duplex voice · hold to talk\nConnect and tap Voice. Encryption is set up automatically.",16));return;}for(Envelope e:selected.messages)if(e.channel.equals(channel.id)){Account a=selected.accounts.get(e.author);messages.addView(label(a==null?e.author:a.name,12));try{byte[] plain=AppSession.core.decrypt(selected,e);if(e.kind.equals("image")){BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(plain,0,plain.length,bounds);if(bounds.outWidth>2048||bounds.outHeight>2048)throw new IOException("Image too large");Bitmap bitmap=BitmapFactory.decodeByteArray(plain,0,plain.length);ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setAdjustViewBounds(true);messages.addView(image,new LinearLayout.LayoutParams(-1,-2));}else messages.addView(label(new String(plain,java.nio.charset.StandardCharsets.UTF_8),16));}catch(Exception ex){messages.addView(label("This archived message needs its original encryption key",14));}}}
    private void join(){LinearLayout p=column();EditText address=edit("IP address or domain",false),password=edit("Server password",true);p.addView(address);p.addView(password);new AlertDialog.Builder(this).setTitle("Join a server").setView(p).setPositiveButton("Join",(d,w)->{SavedServer s=new SavedServer();s.address=address.getText().toString().trim();char[] secret=password.getText().toString().toCharArray();password.setText("");execute(()->{AppSession.core.connect(s,secret);return s;},r->{showMain();servers.setSelection(AppSession.core.state.servers.indexOf(s));});}).setNegativeButton("Cancel",null).show();}
    private void connect(){if(selected!=null)execute(()->{AppSession.core.connect(selected,null);return null;},r->{status.setText("Connected");refreshChannels();});}
    private void send(){if(selected==null||channel==null||input.getText().toString().trim().isEmpty())return;String text=input.getText().toString();execute(()->{AppSession.core.send(selected,channel,"text",Crypto.utf(text));return null;},r->{input.setText("");render();});}
    private void profile(){ClientState s=AppSession.core.state;LinearLayout p=column();EditText name=edit("Display name",false),bio=edit("About you",false);name.setText(s.name);bio.setText(s.bio);p.addView(name);p.addView(bio);p.addView(button("Choose picture (10 KB)",()->pick(2)));if(selected!=null)p.addView(label("Account hash\n"+AppSession.core.account(selected),12));new AlertDialog.Builder(this).setTitle("Your profile").setView(p).setPositiveButton("Save",(d,w)->execute(()->{String n=name.getText().toString().trim(),b=bio.getText().toString();if(n.isEmpty()||n.length()>40||b.length()>240)throw new IOException("Name 1–40 characters; bio up to 240");s.name=n;s.bio=b;AppSession.core.save();for(SavedServer server:s.servers)if(AppSession.core.connected(server))AppSession.core.updateProfile(server);return null;},r->status.setText("Profile saved"))).setNegativeButton("Cancel",null).show();}
    private void audio(){ClientState s=AppSession.core.state;LinearLayout p=column();EditText ice=edit("ICE URLs, comma separated",false);ice.setText(s.iceUrls);SeekBar gain=new SeekBar(this),volume=new SeekBar(this);gain.setMax(200);gain.setProgress(s.inputGain);volume.setMax(200);volume.setProgress(s.outputGain);p.addView(label("Input gain",14));p.addView(gain);p.addView(label("Output volume",14));p.addView(volume);p.addView(ice);p.addView(label("Select microphone and playback device in the voice panel.\nUse the on-screen button or map your hardware PTT key.",14));p.addView(button("Map hardware PTT key",()->{AlertDialog capture=new AlertDialog.Builder(this).setTitle("Press the hardware PTT key").setMessage("Press the side key once, then save audio options.").setNegativeButton("Cancel",null).create();capture.setOnKeyListener((dialog,code,event)->{if(event.getAction()==KeyEvent.ACTION_DOWN&&code!=KeyEvent.KEYCODE_BACK&&code!=KeyEvent.KEYCODE_VOLUME_UP&&code!=KeyEvent.KEYCODE_VOLUME_DOWN){s.hardwarePttCode=code;dialog.dismiss();return true;}return false;});capture.show();}));new AlertDialog.Builder(this).setTitle("Audio options").setView(p).setPositiveButton("Save",(d,w)->execute(()->{s.inputGain=gain.getProgress();s.outputGain=volume.getProgress();s.iceUrls=ice.getText().toString().trim();s.pttKey="F8";AppSession.core.save();return null;},r->{})).setNegativeButton("Cancel",null).show();}
    private void voice(){if(selected==null||channel==null||!channel.type.equals("voice"))return;if(!AppSession.core.connected(selected)||!selected.channelKeys.containsKey(channel.id)){error(new Exception("Reconnect to refresh your channel access"));return;}AppSession.server=selected;AppSession.channel=channel;external=true;startActivity(new Intent(this,VoiceActivity.class));}
    private void pick(int purpose){if(purpose==1&&(selected==null||channel==null||!channel.type.equals("text"))){error(new Exception("Select a text channel first"));return;}pictureServer=selected;pictureChannel=channel;imagePurpose=purpose;external=true;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,100);}
    protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==100&&result==RESULT_OK&&data!=null){android.net.Uri uri=data.getData();execute(()->{byte[] bytes;try(InputStream in=getContentResolver().openInputStream(uri)){bytes=Io.read(in,20000001);}if(bytes.length>20000000)throw new IOException("Source image exceeds 20 MB");BitmapFactory.Options b=new BitmapFactory.Options();b.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,b);if(b.outWidth<1||b.outHeight<1||(long)b.outWidth*b.outHeight>40000000)throw new IOException("Invalid still image");if(!Set.of("image/png","image/jpeg","image/webp").contains(b.outMimeType))throw new IOException("Choose PNG, JPEG or WebP");b.inJustDecodeBounds=false;b.inSampleSize=Math.max(1,Math.max(b.outWidth,b.outHeight)/2000);Bitmap original=BitmapFactory.decodeByteArray(bytes,0,bytes.length,b);int limit=imagePurpose==2?10000:100000;byte[] webp=null;for(int side=imagePurpose==2?256:1600;side>=32&&webp==null;side=side*3/4){float scale=Math.min(1,(float)side/Math.max(original.getWidth(),original.getHeight()));Bitmap resized=Bitmap.createScaledBitmap(original,Math.max(1,(int)(original.getWidth()*scale)),Math.max(1,(int)(original.getHeight()*scale)),true);for(int quality:new int[]{82,60,40,20}){ByteArrayOutputStream out=new ByteArrayOutputStream();resized.compress(Bitmap.CompressFormat.WEBP,quality,out);if(out.size()<=limit){webp=out.toByteArray();break;}}if(resized!=original)resized.recycle();}original.recycle();if(webp==null)throw new IOException("Image does not fit limit");if(imagePurpose==2){AppSession.core.state.avatar=Crypto.b64(webp);AppSession.core.save();for(SavedServer s:AppSession.core.state.servers)if(AppSession.core.connected(s))AppSession.core.updateProfile(s);}else AppSession.core.send(pictureServer,pictureChannel,"image",webp);return null;},r->{status.setText("Image saved");render();});}}
    private LinearLayout column(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(12,12,12,12);return p;}
    private TextView label(String text,int size){TextView t=new TextView(this);t.setText(text);t.setTextSize(size);t.setTextColor(Color.rgb(22,22,22));t.setPadding(8,8,8,8);t.setTextIsSelectable(true);return t;}
    private EditText edit(String hint,boolean password){EditText e=new EditText(this);e.setHint(hint);if(password)e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);return e;}
    private Button button(String name,Runnable action){Button b=new Button(this);b.setText(name);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.rgb(15,98,254)));b.setOnClickListener(v->action.run());return b;}
    private interface Operation{Object run()throws Exception;}
    private void execute(Operation op,java.util.function.Consumer<Object> done){if(busy)return;busy=true;work.submit(()->{try{Object result=op.run();runOnUiThread(()->{busy=false;done.accept(result);});}catch(Exception e){runOnUiThread(()->{busy=false;error(e);if(AppSession.core==null&&!isFinishing())unlock();});}});}
    private void error(Exception e){if(!isFinishing())new AlertDialog.Builder(this).setTitle("VCH").setMessage(e.getMessage()).setPositiveButton("OK",null).show();}
    private abstract static class Selection implements AdapterView.OnItemSelectedListener{public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){chosen(i);}abstract void chosen(int i);}
}
